async function openAgentSettings(){
  const requestId=state.agentCatalogRequest=(state.agentCatalogRequest??0)+1;
  const draft=agentSettingsDraft();
  agentSettingsDialog(state.canConfigureAgent&&state.data.modelReady);
  restoreAgentSettingsDraft(draft);
  if(!state.canConfigureAgent||!state.data.modelReady)return;
  let catalog;
  try{catalog=await api('/api/agent/models');}catch(error){catalog={models:[{id:state.data.modelName,name:state.data.modelName,provider:'Current selection'}],notice:error.message};}
  if(requestId!==state.agentCatalogRequest)return;
  state.modelCatalog=catalog;
  if(document.querySelector('#agent-settings-form')){const edited=agentSettingsDraft();agentSettingsDialog();restoreAgentSettingsDraft(edited);}
}
function agentSettingsDraft(){const form=document.querySelector('#agent-settings-form');return form?{model:form.elements.model.value,instructions:form.elements.instructions.value,custom:document.querySelector('#agent-custom-model').value}:null;}
function restoreAgentSettingsDraft(draft){
  if(!draft)return;const form=document.querySelector('#agent-settings-form');
  const listed=[...form.elements.model.options].some(o=>o.value===draft.model);
  form.elements.model.value=listed?draft.model:'custom';form.elements.instructions.value=draft.instructions;
  document.querySelector('#agent-custom-model').value=listed?draft.custom:draft.model;
  document.querySelector('#agent-custom-field').hidden=form.elements.model.value!=='custom';
}
