function importDialog(){modal('Import a bank statement','CSV columns are mapped explicitly. Incoming posted payments only.',`<form id="import-form"><div class="field"><label for="statement-file">CSV file</label><input id="statement-file" type="file" accept=".csv,text/csv" required></div><div class="field"><label for="statement-account">Bank account identifier</label><input id="statement-account" name="accountId" placeholder="e.g. qonto-operating-eur" required></div><div class="field-row">${[['id','Transaction ID','id'],['amount','Amount','amount'],['currency','Currency','currency'],['bookedAt','Date','date'],['senderName','Sender','sender'],['reference','Reference','reference']].map(([key,label,value])=>`<div class="field"><label for="column-${key}">${label} column</label><input id="column-${key}" name="${key}" value="${value}" required></div>`).join('')}</div><div class="field"><label for="amount-unit">Amount format</label><select id="amount-unit"><option value="major">Major units (123.45 = €123.45)</option><option value="minor">Minor units (12345 = €123.45)</option></select></div><p class="error-inline" id="import-error"></p></form>`,`${button('Cancel','close')}<button class="button primary" type="submit" form="import-form">Import payments</button>`);}
const chatDrafts=new Map();
async function switchChat(id){
  if(state.sending||state.busy||state.loadingChat)return toast('Wait for the current action to finish.');
  if(id===state.threadId){document.querySelector('#chat-switcher')?.removeAttribute('open');document.querySelector('#message')?.focus();return;}
  state.loadingChat=true;
  try{
    const messages=id?(await api(`/api/threads/${encodeURIComponent(id)}/messages`)).messages:[];
    chatDrafts.set(state.threadId,document.querySelector('#message')?.value??'');
    state.threadId=id;state.messages=messages;
    if(id)localStorage.setItem('lago-thread',id);else localStorage.removeItem('lago-thread');
    const composer=document.querySelector('#message');if(composer)composer.value=chatDrafts.get(id)??'';
    render();scrollChat();document.querySelector('#message')?.focus();
  }finally{state.loadingChat=false;}
}
let threadCreation;
async function ensureThread(){if(!state.threadId){threadCreation??=api('/api/threads',{});try{const t=await threadCreation;chatDrafts.delete(null);state.threadId=t.id;localStorage.setItem('lago-thread',t.id);if(!state.data.threads.some(x=>x.id===t.id))state.data.threads.unshift(t);}finally{threadCreation=null;}}return state.threadId;}
async function sendMessage(text){if(state.sending||state.loadingChat||!text.trim())return;await ensureThread();state.messages.push({role:'user',text});state.sending=true;state.thinking='Reading your workspace…';const composer=document.querySelector('#message');if(composer)composer.value='';render();scrollChat();
  try {const response=await fetch('/api/chat',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':state.csrf,'x-admin-key':sessionStorage.getItem('lago-key')??''},body:JSON.stringify({threadId:state.threadId,message:text})});if(!response.ok)throw new Error((await response.json()).error);const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
    while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines.filter(Boolean)){const event=JSON.parse(line);if(event.type==='status')state.thinking=event.text;if(event.type==='message'){state.messages.push(event.message);state.thinking=null;await refresh(false);}render();scrollChat();}}
  }catch(error){toast(error.message);state.messages=(await api(`/api/threads/${state.threadId}/messages`)).messages;}finally{state.sending=false;state.thinking=null;await refresh(false);render();scrollChat();document.querySelector('#message')?.focus();}}
function scrollChat(){requestAnimationFrame(()=>{const el=document.querySelector('#chat-scroll');if(el)el.scrollTop=el.scrollHeight;});}
async function run(kind='dunning',previewId=null){state.busy=true;render();try{if(state.page==='chat')await ensureThread();const result=await api('/api/runs',{kind,mode:previewId?'drafts':'preview',previewId,threadId:state.page==='chat'?state.threadId:null});await refresh();if(state.page==='chat'){state.messages=(await api(`/api/threads/${state.threadId}/messages`)).messages;render();scrollChat();}if(previewId){dialog.close();state.page='drafts';state.draftFilter='pending';location.hash='drafts';render();}else runDetail(result.id);toast(previewId?'Drafts saved. Review an email to approve sending.':'Your preview is ready.');}catch(error){await refresh();const failed=error.value?.id;if(failed)runDetail(failed);else toast(error.message);}finally{state.busy=false;render();}}
document.addEventListener('click',async event=>{
  if(!event.target.closest('.chat-switcher'))document.querySelector('#chat-switcher')?.removeAttribute('open');
  const target=event.target.closest('button');if(!target||target.disabled)return;
  try {
    if(target.dataset.page){dialog.close();state.page=target.dataset.page;location.hash=state.page;render();return;}
    if(target.dataset.prompt){await sendMessage(target.dataset.prompt);return;}
    if(target.dataset.filter){state.filter=target.dataset.filter;render();return;}
    if(target.dataset.draftFilter){state.draftFilter=target.dataset.draftFilter;render();return;}
    if(target.dataset.runFilter){state.runFilter=target.dataset.runFilter;render();return;}
    const action=target.dataset.action,id=target.dataset.id;if(!action)return;
    if(action==='close'){dialog.close();return;}if(action==='reload'){await boot();return;}
    if(action==='connections'){connections();return;}
    if(action==='email-resend-preset'){state.emailSettings={...state.emailSettings,host:'smtp.resend.com',port:465,security:'tls',username:'resend',from:'onboarding@resend.dev',hasPassword:false,checkedAt:null,message:null};emailDialog();return;}
    if(action==='email-settings'){state.emailReturnDraft=null;state.emailSettings=await api('/api/admin/email');emailDialog();return;}
    if(action==='email-check'){target.disabled=true;target.textContent='Checking…';try{await api('/api/admin/email/check',{});toast('SMTP verified. No email was sent.');}catch(error){toast(error.message);}finally{await refresh(false);state.emailSettings=await api('/api/admin/email');emailDialog();}return;}
    if(action==='agent-settings'||action==='agent-models'){await openAgentSettings();return;}
    if(action==='schedule'||action==='edit-schedule'){scheduleDialog(id,target.dataset.kind??'dunning');return;}
    if(action==='payment-detail'){paymentDetail(id);return;}if(action==='run-detail'){runDetail(id);return;}
    if(action==='import'){importDialog();return;}
    if(action==='new-chat'||action==='open-chat'){await switchChat(action==='new-chat'?null:id);return;}
    if(action==='preview'||action==='reconcile'){await run(action==='preview'?'dunning':'reconciliation');return;}
    if(action==='sender-settings'){state.emailSettings=await api('/api/admin/email');if(!state.emailSettings.host){state.emailReturnDraft=id;emailDialog();return;}senderDialog(id);return;}
    if(action==='alert-settings'){alertSettingsDialog();return;}
    if(action==='dunning-settings'){dunningSettingsDialog();return;}
    if(action==='customer-memory'){state.memoryReturn=null;customerMemory();return;}
    if(action==='customer-history'){state.memoryReturn=target.dataset.run?{action:'run-detail',id:target.dataset.run}:target.dataset.draft?{action:'review-draft',id:target.dataset.draft}:null;await customerHistory(id);return;}
    if(action==='memory-tab'){renderCustomerHistory(target.dataset.tab);return;}
    if(action==='memory-more'){renderCustomerHistory('activity',Number(target.dataset.limit));return;}
    if(action==='review-customer'){customerReview(id);return;}
    if(action==='memory-pause'){await api('/api/customers/pause',{customerId:id,paused:target.dataset.paused!=='true',reason:'Changed by workspace operator'});await refresh();await customerHistory(id);return;}
    if(action==='discard-draft'){await api(`/api/drafts/${id}/discard`,{});await refresh();reviewDraft(id);toast('Draft discarded. A future run can prepare a fresh reminder.');return;}
    if(action==='review-draft'){reviewDraft(id);return;}
    if(action==='refresh-dunning-draft'){target.disabled=true;target.textContent='Refreshing…';try{await api(`/api/drafts/${id}/refresh`,{});await refresh();reviewDraft(id);toast('Draft updated. Review the new content before sending.');}catch(error){await refresh();reviewDraft(id);toast(error.message);}return;}
    if(action==='refresh-draft-link'){
      target.disabled=true;target.textContent='Refreshing…';
      try{await api(`/api/drafts/${id}/refresh-link`,{});await refresh();reviewDraft(id);toast('Billing link refreshed. Review the draft before sending.');}
      catch(error){await refresh();reviewDraft(id);toast(error.message);}return;
    }
    if(action==='send-draft'){
      target.disabled=true;target.textContent='Sending…';
      try{const sent=await api(`/api/drafts/${id}/send`,{});await refresh();reviewDraft(id);toast('Email submitted. Check your inbox and spam folder.');}
      catch(error){await refresh();const draft=state.data.drafts?.find(d=>d.id===id);if(draft)reviewDraft(id);toast(error.message);}return;
    }
    if(action==='confirm-dunning'){const r=state.data.runs.find(r=>r.id===id);modal('Save drafts?', 'Invoices and received payments will be checked again first.',`<div class="notice">Save the ${r.result.collection.ready} ready reminders as drafts in this workspace. Review them in Drafts. Saving drafts does not send emails or retry charges. You can send each saved draft manually to the configured recipient.</div>`,`${button('Cancel','close')}${button('Create drafts','execute-dunning',`data-id="${id}"`,'primary')}`);return;}
    if(action==='execute-dunning'){dialog.close();await run('dunning',id);return;}
    if(action==='toggle-schedule'){target.disabled=true;await api(`/api/schedules/${id}`,{enabled:!state.data.schedules.find(s=>s.id===id).enabled},'PATCH');await refresh();return;}
    if(action==='delete-schedule'){modal('Delete this schedule?','Previous runs will remain in your history.',`<p class="small muted">${esc(state.data.schedules.find(s=>s.id===id)?.name)}</p>`,`${button('Keep schedule','close')}${button('Delete schedule','delete-schedule-confirm',`data-id="${id}"`,'danger')}`);return;}
    if(action==='delete-schedule-confirm'){await api(`/api/schedules/${id}`,undefined,'DELETE');dialog.close();await refresh();toast('Schedule deleted.');return;}
    if(['approve-payment','reject-payment','hold-payment'].includes(action)) {
      const proposalId=Number(target.dataset.proposal),rememberIdentity=Boolean(document.querySelector('#remember-identity')?.checked);
      if(action==='approve-payment'&&state.data.allowLive){modal('Record this payment in Lago?','This records an already received payment. It does not charge the customer.',`<p class="small muted">The invoice balance and payment reference will be rechecked before writing.</p>`,`${button('Cancel','close')}${button('Approve & record','record-payment',`data-id="${esc(id)}" data-proposal="${proposalId}" data-remember="${rememberIdentity}"`,'primary')}`);return;}
      target.disabled=true;await api('/api/reviews',{action:action==='approve-payment'?'approve':action==='reject-payment'?'reject':'hold',transferId:id,proposalId,rememberIdentity});await refresh();paymentDetail(id);toast(action==='approve-payment'?'Allocation approved.':action==='reject-payment'?'Match rejected. The payment remains available to match.':'Payment held for review.');return;
    }
    if(action==='record-payment'){target.disabled=true;await api('/api/reviews',{action:'approve',transferId:id,proposalId:Number(target.dataset.proposal),execute:true,rememberIdentity:target.dataset.remember==='true'});dialog.close();await refresh();toast('Payment recorded in Lago.');return;}
    if(action==='record-manual-payment'){target.disabled=true;await api('/api/reviews',{...state.manualPayment,execute:true});state.manualPayment=null;dialog.close();await refresh();toast('Payment recorded in Lago.');return;}
    if(action==='execute-payment'){modal('Record the approved payment?','The current invoice balance will be checked again.',`<p class="small muted">This creates a payment record in Lago for money already received.</p>`,`${button('Cancel','close')}${button('Record payment','execute-payment-confirm',`data-decision="${target.dataset.decision}"`,'primary')}`);return;}
    if(action==='execute-payment-confirm'){await api('/api/decisions/execute',{decisionId:Number(target.dataset.decision)});dialog.close();await refresh();toast('Payment recorded.');return;}
    if(action==='void-payment'){modal('Correct this allocation?','Unexecuted approvals are voided. Executed payments require a reviewed reversal.',`<p class="small muted">The audit history will be preserved.</p>`,`${button('Cancel','close')}${button('Confirm correction','void-payment-confirm',`data-decision="${target.dataset.decision}"`,'danger')}`);return;}
    if(action==='void-payment-confirm'){await api('/api/decisions/void',{decisionId:Number(target.dataset.decision),reason:'Operator correction from payment review'});dialog.close();await refresh();toast('Correction recorded.');return;}
    if(action==='pause-customer'||action==='resume-customer'){await api('/api/customers/pause',{customerId:id,paused:action==='pause-customer'});await refresh(false);if(target.dataset.run)runDetail(target.dataset.run);toast(action==='pause-customer'?'Automatic checks paused.':'Automatic checks resumed. No email was sent.');return;}
  }catch(error){target.disabled=false;toast(error.message);}
});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;
  if(form.id==='sender-settings-form'){
    const submit=dialog.querySelector('[form="sender-settings-form"]'),draftId=form.dataset.draftId;
    submit.disabled=true;submit.textContent='Saving…';
    try{const e=state.emailSettings;await api('/api/admin/email/settings',{host:e.host,port:e.port,security:e.security,username:e.username,from:form.elements.from.value.trim(),password:'',keepPassword:e.hasPassword});await refresh();if(draftId)reviewDraft(draftId);else dialog.close();toast('Sender saved. No email was sent.');}
    catch(error){document.querySelector('#sender-settings-error').textContent=error.message;submit.disabled=false;submit.textContent='Save sender';}return;
  }
  if(form.id==='email-settings-form'){
    const submit=dialog.querySelector('[form="email-settings-form"]');submit.disabled=true;submit.textContent='Checking…';
    try{const values=Object.fromEntries(new FormData(form));values.keepPassword=Boolean(state.emailSettings?.hasPassword);state.emailSettings=await api('/api/admin/email/settings',values);form.reset();await refresh(false);const draftId=state.emailReturnDraft;state.emailReturnDraft=null;if(draftId)reviewDraft(draftId);else dialog.close();toast('SMTP saved and verified. No email was sent.');}
    catch(error){document.querySelector('#email-settings-error').textContent=error.message;submit.disabled=false;submit.textContent=state.emailSettings?.host==='smtp.resend.com'?'Connect Resend':'Check & save';}return;
  }
  if(form.id==='alert-settings-form'){
    const submit=dialog.querySelector('[form="alert-settings-form"]');submit.disabled=true;
    try{const data=Object.fromEntries(new FormData(form));data.enabled=form.elements.enabled.checked;data.revision=Number(form.dataset.revision);await api('/api/agent/alerts',data);form.elements.webhook.value='';await refresh();dialog.close();toast('Alert settings saved. No alert was sent.');}
    catch(error){document.querySelector('#alert-settings-error').textContent=error.message;submit.disabled=false;}return;
  }
  if(form.id==='dunning-settings-form'){
    const submit=dialog.querySelector('[form="dunning-settings-form"]');submit.disabled=true;
    try{await api('/api/agent/dunning-settings',{...Object.fromEntries(new FormData(form)),revision:Number(form.dataset.revision)});await refresh();dialog.close();toast('Dunning settings saved.');}
    catch(error){document.querySelector('#dunning-settings-error').textContent=error.message;submit.disabled=false;}return;
  }
  if(form.id==='agent-settings-form'){
    const submit=dialog.querySelector('[form="agent-settings-form"]'),values=Object.fromEntries(new FormData(form));
    if(values.model==='custom')values.model=document.querySelector('#agent-custom-model').value.trim();
    values.revision=Number(form.dataset.revision);for(const input of form.elements)input.disabled=true;submit.textContent='Checking connection…';
    try{await api('/api/agent/settings',values);await refresh();dialog.close();toast('Agent settings saved. Your next message will use this model.');}
    catch(error){const output=document.querySelector('#agent-settings-error');if(output){output.textContent=error.message+' Your saved model is unchanged.';document.querySelector('#agent-policy-help').hidden=error.value?.code!=='model_retention_policy';}else toast(error.message);for(const input of form.elements)input.disabled=false;submit.textContent='Check & save';}
    return;
  }
  if(form.id==='chat-form'){await sendMessage(document.querySelector('#message').value);return;}
  if(form.id==='login-form'){sessionStorage.setItem('lago-key',document.querySelector('#access-key').value);try{const session=await api('/api/session');state.csrf=session.csrf;dialog.close();await boot();}catch(error){document.querySelector('#login-error').textContent=error.message;}return;}
  if(form.id==='manual-payment-form'){const payload={action:'approve',transferId:form.dataset.id,allocations:[{invoiceId:document.querySelector('#manual-invoice').value,amountCents:Math.round(Number(document.querySelector('#manual-amount').value)*factor(state.data.transfers.find(t=>t.id===form.dataset.id).currency))}]};if(state.data.allowLive){state.manualPayment=payload;modal('Record this manual allocation?','The invoice and received amount will be verified before recording.',`<p class="small muted">This records received money in Lago. It does not charge the customer.</p>`,`${button('Cancel','close')}${button('Record payment','record-manual-payment','','primary')}`);}else{try{await api('/api/reviews',payload);await refresh();paymentDetail(payload.transferId);toast('Allocation approved.');}catch(error){toast(error.message);}}return;}
  if(form.id==='schedule-form'){const submit=dialog.querySelector('[form="schedule-form"]');submit.disabled=true;try{const data=Object.fromEntries(new FormData(form));const existing=state.data.schedules.find(s=>s.id===form.dataset.id);data.enabled=existing?.enabled??true;await api(form.dataset.id?`/api/schedules/${form.dataset.id}`:'/api/schedules',data,form.dataset.id?'PATCH':'POST');dialog.close();state.page='runs';location.hash='runs';await refresh();toast('Schedule saved.');}catch(error){document.querySelector('#schedule-error').textContent=error.message;}finally{submit.disabled=false;}return;}
  if(form.id==='customer-review-form'){const submit=dialog.querySelector('[form="'+form.id+'"]');submit.disabled=true;try{
    const id=form.dataset.id,data={note:form.elements.note.value};
    data.resetCadence=form.elements.resetCadence.checked;await api(`/api/customers/${encodeURIComponent(id)}/review`,data);await refresh();await customerHistory(id);
  }catch(error){document.querySelector('#review-error').textContent=error.message;submit.disabled=false;}return;}
  if(form.id==='import-form'){const submit=dialog.querySelector('[form="import-form"]');submit.disabled=true;try{const file=document.querySelector('#statement-file').files[0];if(file.size>800000)throw new Error('Use a CSV file smaller than 800 KB.');const mapping=Object.fromEntries([...form.querySelectorAll('[id^="column-"]')].map(i=>[i.name,i.value]));await api('/api/statements',{format:'csv',content:await file.text(),accountId:form.elements.accountId.value,sourceSystem:'statement_csv',mapping,amountUnit:document.querySelector('#amount-unit').value});dialog.close();await refresh();toast('Statement imported.');}catch(error){document.querySelector('#import-error').textContent=error.message;}finally{submit.disabled=false;}return;}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const switcher=document.querySelector('#chat-switcher[open]');if(switcher){switcher.removeAttribute('open');switcher.querySelector('summary').focus();event.preventDefault();return;}}if(event.target.id==='message'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendMessage(event.target.value);}});
document.addEventListener('input',event=>{if(event.target.id==='payment-search'){const pos=event.target.selectionStart;state.search=event.target.value;render();const input=document.querySelector('#payment-search');input.focus();input.setSelectionRange(pos,pos);}if(['schedule-cron','schedule-timezone'].includes(event.target.id))previewSchedule();});
document.addEventListener('change',event=>{if(event.target.id==='schedule-kind'){updateScheduleTask();return;}if(event.target.id==='agent-model'){document.querySelector('#agent-custom-field').hidden=event.target.value!=='custom';return;}if(event.target.id==='schedule-frequency'){const custom=event.target.value==='custom';document.querySelector('#cron-field').hidden=!custom;if(!custom)document.querySelector('#schedule-cron').value=event.target.value;previewSchedule();}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(names[page]){state.page=page;render();}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const bounds=dialog.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)dialog.close();}});
const fingerprint=data=>JSON.stringify({runs:data.runs.map(r=>[r.id,r.status]),drafts:data.drafts.map(d=>[d.id,d.status,d.send_detail]),email:data.email,schedules:data.schedules,transfers:data.transfers.map(t=>[t.id,t.reviewStatus,t.proposals]),busy:data.busy});
setInterval(async()=>{if(state.sending||state.busy||dialog.open||!state.data)return;try{const previous=fingerprint(state.data);await refresh(false);if(state.page!=='chat'&&previous!==fingerprint(state.data)&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render();}catch{}},20000);
boot();

document.addEventListener('change',event=>{if(event.target.id==='alert-channel'){document.querySelector('#alert-email-field').hidden=event.target.value!=='email';document.querySelector('#alert-slack-field').hidden=event.target.value!=='slack';}});
